const URL = [
			"https://coolors.co/03071e-370617-6a040f-9d0208-d00000-dc2f02-e85d04-f48c06-faa307-ffba08",
			"https://coolors.co/1b395d-3c6aa5-c3d4ee-2d361a-427532-ffd20c-337783-3da2b4-2f8f84-74c7b5",
			"https://coolors.co/54478c-2c699a-048ba8-0db39e-16db93-83e377-b9e769-efea5a-f1c453-f29e4c"
	]
let COLS;

function setup() {
	const s = (windowWidth, windowHeight) * 0.9;
	createCanvas(s / 4 * 3, s );
	background(255);
	frameRate(1);
}

function draw() {
	let y = 0;
	let _wG_1 = 0; while ((y < height) && ++_wG_1 < 20000)
	{
		const h = random(0.05, 0.2) * width;
		let p = createRandPatternParam(5, random(0.07, 0.1)* width, createCols(random(URL)));
		let x = 0;
		let _wG_2 = 0; while ((x < width) && ++_wG_2 < 20000)
		{
			let w = random(0.1, 0.2) * width;
			//p.bc = shuffle(p.bc);
			p = shuffleParam(p, 10);
			p = shuffleParam(p, 10);
			RectPatternParam(x, y, w + 1, h + 2, p);
			x += w;
		}
		y += h;
	}
}


function shuffleParam(p, num = 10)
{
	let tar;
	let rn = random();
	if(rn < 0.33)tar = p.func;
	else if(rn < 0.66)tar = p.bc;
	else tar = p.pc;

	for(let i = 0; i < num; i++)
	{
		let i1 = int(random(tar.length));
		let i2 = int(random(tar.length));
		let cache1 = tar[i1];
		let cache2 = tar[i2];
		tar[i1] = cache2;
		tar[i2] = cache1;
	}
	return p;
}


function RectPatternParam(_x, _y, _w, _h, p)
{
	rectPatternArr(_x, _y, _w, _h, p.func, p.pw, p.ph, p.bc, p.pc);
}


////////////////

function createRandPatternParam(min, max, colArr)
{
	let f = [c, c2, c3, c4];
	let ptnW = randNumArr(50, min, max);
	let ptnH = randNumArr(50, min, max);
	let col = randColArr(50, colArr);
	let bc = col[0];
	let pc = col[1];

	return {func : f, pw : ptnW, ph : ptnH, bc : bc, pc : pc};
}

function randNumArr(num, min = 5, max = 15)
{
	let r = [];
	for(let i = 0; i < num; i++)
	{
		r[i] = random(min, max);
	}
	return r;
}

function randColArr(num, colArray)
{
	let c1 = [];
	let indexCache = [];
	let index = int(random(colArray.length));
	for(let i = 0; i < num; i++)
	{
		c1[i] = colArray[index];
		indexCache[i] = index;
		index += int(random(1, colArray.length - 1));
		index = index % colArray.length;
	}

	let c2 = [];
	for(let i = 0; i < num; i++)
	{
		let index = indexCache[i] + int(random(1, colArray.length - 1));
		index = index % colArray.length;
		c2[i] = colArray[index];
	}

	return [c1, c2];
}



////////////////

function rectPatternArr(_x, _y, _w, _h,
											_funcArr,
											_ptnWArr, _ptnHArr,
											_baseColArr, _ptnColArr,
										 )
{
	if(_renderer._rectMode === CENTER)
	{
		_x -= _w / 2;
		_y -= _h / 2;
	}

	fill(255, 0);
	noStroke();
	rectMode(CORNER);

	push();
	translate(_x, _y);
	rect(0, 0, _w, _h);
	push();
	drawingContext.clip();
	let dy = 0;
	let count = 0;
	let _wG_3 = 0; while ((dy < _h) && ++_wG_3 < 20000)
	{
		let spanW = _ptnWArr[count % _ptnWArr.length];
		spanW = _w / int(_w / spanW);
		let spanH = _ptnHArr[count % _ptnHArr.length];
		if(dy + spanH > _h) spanH = _h - dy + 1;
		let func = _funcArr[count % _funcArr.length];
		let baseCol = _baseColArr[count % _baseColArr.length];
		let ptnCol = _ptnColArr[count % _ptnColArr.length];

		fill(baseCol);
		rectMode(CORNER);
		rect(0, dy, _w, spanH);

		fill(ptnCol);
		for(let dx = 0; dx < _w; dx += (Math.max(0.001, Math.abs(spanW)) || 1))
		{
			push();
			translate(dx + spanW / 2, dy + spanH / 2);
			func(spanW , spanH);
			pop();
		}
		dy += spanH;
		count++;
	}

	pop();
	pop();

}






////////////////

function c(_w, _h)
{
	ellipseMode(CENTER);
	rectMode(CENTER);
	noStroke();
	ellipse(0, 0, min(_w, _h) * 0.8);
}

function c2(_w, _h)
{
	ellipseMode(CENTER);
	rectMode(CENTER);
	noStroke();
	rect(0, 0, _w * 0.5, _h * 0.5);
}

function c3(_w, _h)
{
	const we = min(_w, _h) * 0.15;
	ellipseMode(CENTER);
	rectMode(CENTER);
	noStroke();
	rect(0, 0, _w * 0.7, we);
	rect(0, 0, we, _h * 0.7);
}

function c4(_w, _h)
{
	noStroke();
	triangle(-_w /2, _h / 2, 0, -_h / 2, _w /2, _h / 2);
}




